.jcw-right-sidebar {
  position: fixed;
  top: 0;
  right: 0;
  width: 320px;
  max-width: 85vw;
  height: 100vh;
  background: #ffffff;
  box-shadow: -12px 0 32px rgba(15, 23, 42, 0.12);
  transform: translateX(100%);
  transition: transform 0.3s ease;
  z-index: 60;
}

.jcw-right-sidebar.is-open {
  transform: translateX(0);
}

.jcw-right-sidebar-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.35);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s ease, visibility 0.2s ease;
  z-index: 55;
}

.jcw-right-sidebar-overlay.is-open {
  opacity: 1;
  visibility: visible;
}

/* JCW dropdown menus */
.jcw-dropdown {
  position: relative;
}

.jcw-dropdown::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 100%;
  height: 8px;
}

  .jcw-dropdown-menu {
    display: none;
    z-index: 60;
    min-width: 720px;
    left: 50%;
    transform: translateX(-50%);
    transform-origin: top center;
  }
  
  .jcw-megamenu-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 20px;
  }

.jcw-megamenu-title {
  font-size: 15px;
}

.jcw-megamenu-subtitle {
  font-size: 13px;
}

.jcw-megamenu-more {
  text-align: left;
}

.jcw-dropdown:hover .jcw-dropdown-menu {
  display: block;
}

.jcw-dropdown-menu.is-open {
    display: block;
}

.jcw-logo-dark {
  display: none;
}

.jcw-nav-scrolled .jcw-logo-light {
  display: none;
}

.jcw-nav-scrolled .jcw-logo-dark {
  display: inline-block !important;
}

@media (max-width: 1024px) {
  .jcw-megamenu-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 768px) {
  .jcw-dropdown-menu {
    position: static;
    margin-top: 0;
    box-shadow: none;
    border: 0;
    min-width: 0;
    left: auto;
    transform: none;
    width: 100%;
  }

  .jcw-dropdown .jcw-dropdown-menu {
    display: none;
  }

  .jcw-dropdown:hover .jcw-dropdown-menu {
    display: none;
  }

  .jcw-dropdown:focus-within .jcw-dropdown-menu {
    display: none;
  }

  .jcw-dropdown-menu.is-open {
    display: block;
  }

  .jcw-dropdown [data-jcw-dropdown-toggle][aria-expanded="true"] + .jcw-dropdown-menu {
    display: block;
  }

  .jcw-megamenu-grid {
    grid-template-columns: 1fr;
  }
}

.jcw-page {
  min-height: 100vh;
}

.jcw-page-hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #1e3a8a 0%, #5b21b6 50%, #4338ca 100%);
}

.jcw-page-hero__container,
.jcw-page-section__container {
  max-width: 80rem;
  margin: 0 auto;
  padding-left: 1rem;
  padding-right: 1rem;
}

.jcw-page-hero__container {
  position: relative;
  z-index: 1;
  padding-top: 5rem;
  padding-bottom: 8rem;
}

.jcw-page-hero__content {
  max-width: 64rem;
  margin: 0 auto;
  text-align: center;
  color: #fff;
}

.jcw-page-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(8px);
  font-size: 0.875rem;
  font-weight: 500;
  margin-bottom: 2rem;
}

.jcw-page-badge__dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 9999px;
  background: #4ade80;
}

.jcw-page-title {
  margin: 0 0 1.5rem;
  font-size: 3rem;
  line-height: 1.05;
  font-weight: 700;
  color: transparent;
  background: linear-gradient(90deg, #fff 0%, #bfdbfe 100%);
  -webkit-background-clip: text;
  background-clip: text;
}

.jcw-page-intro {
  max-width: 64rem;
  margin: 0 auto 3rem;
  font-size: 1.25rem;
  line-height: 1.6;
  color: #dbeafe;
}

.jcw-page-section {
  padding: 4rem 0;
  background: #f9fafb;
}

.jcw-page-stack {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.jcw-card-grid,
.jcw-split-grid {
  display: grid;
  gap: 1.5rem;
}

.jcw-card-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.jcw-split-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.jcw-choice-card,
.jcw-content-card,
.jcw-cta-card {
  border-radius: 1rem;
  border: 1px solid #e2e8f0;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.08);
}

.jcw-choice-card {
  padding: 1.5rem;
}

.jcw-choice-card--light {
  border-color: rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.jcw-content-card {
  padding: 2rem;
  background: #fff;
}

.jcw-content-card--muted {
  background: #f8fafc;
}

.jcw-content-card--center {
  text-align: center;
}

.jcw-card-label {
  margin: 0;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.jcw-card-label--hero {
  color: #dbeafe;
}

.jcw-card-title {
  margin: 0.75rem 0 0;
  font-size: 1.5rem;
  line-height: 1.3;
  font-weight: 700;
}

.jcw-card-text {
  margin-top: 0.75rem;
  color: #475569;
  line-height: 1.6;
}

.jcw-choice-card--light .jcw-card-text {
  color: #dbeafe;
}

.jcw-section-title {
  margin: 0 0 1.5rem;
  font-size: 1.875rem;
  line-height: 1.3;
  font-weight: 700;
  color: #111827;
}

.jcw-section-text {
  color: #374151;
  line-height: 1.7;
}

.jcw-button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.jcw-button-row--center {
  justify-content: center;
}

.jcw-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  font-weight: 600;
  transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.jcw-button--light {
  background: #fff;
  color: #1e3a8a;
}

.jcw-button--light:hover {
  background: #eff6ff;
}

.jcw-button--primary {
  background: #2563eb;
  color: #fff;
}

.jcw-button--primary:hover {
  background: #1d4ed8;
}

.jcw-button--ghost-light {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.jcw-button--ghost-light:hover {
  background: rgba(255, 255, 255, 0.2);
}

.jcw-table-wrap {
  overflow-x: auto;
}

.jcw-compare-table {
  width: 100%;
  border-collapse: collapse;
}

.jcw-compare-table th,
.jcw-compare-table td {
  padding: 1rem 1.5rem 1rem 0;
  border-bottom: 1px solid #e2e8f0;
  text-align: left;
  vertical-align: top;
  color: #334155;
}

.jcw-compare-table th {
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #64748b;
}

.jcw-compare-table td:first-child {
  font-weight: 600;
  color: #0f172a;
}

.jcw-checklist {
  margin: 1rem 0 0;
  padding-left: 1.25rem;
  color: #334155;
}

.jcw-checklist li + li {
  margin-top: 0.75rem;
}

.jcw-cta-card {
  padding: 2rem;
  background: #0f172a;
  color: #fff;
}

.jcw-cta-card .jcw-section-title,
.jcw-cta-card .jcw-card-text {
  color: inherit;
}

@media (max-width: 768px) {
  .jcw-page-hero__container {
    padding-top: 5rem;
    padding-bottom: 6rem;
  }

  .jcw-page-title {
    font-size: 2.5rem;
  }

  .jcw-page-intro {
    font-size: 1.125rem;
  }

  .jcw-card-grid,
  .jcw-split-grid {
    grid-template-columns: 1fr;
  }
}
/* Main-site visual contrast tokens */
:root {
  --jcw-blue-primary: #2563eb;
  --jcw-home-neutral-light: #fcfdfe;
  --jcw-home-neutral-alt: #dbdbdc;
  --jcw-home-border: #a4a5a7;
  --jcw-main-nav-hero: #f8fafc;
  --jcw-main-nav-hover: #ffffff;
  --jcw-main-nav-scrolled: #14214a;
  --jcw-main-footer: var(--jcw-blue-primary);
  --jcw-main-footer-strip: var(--jcw-blue-primary);
}

.jcw-main-nav-link,
.jcw-main-nav-link:visited {
  color: var(--jcw-main-nav-hero);
}

.jcw-main-nav-link:hover,
.jcw-main-nav-link:focus-visible {
  color: var(--jcw-main-nav-hover);
}

[data-jcw-main-nav].jcw-nav-scrolled .jcw-main-nav-link,
[data-jcw-main-nav].jcw-nav-scrolled .jcw-main-nav-link:visited {
  color: var(--jcw-main-nav-scrolled);
}

[data-jcw-main-nav].jcw-nav-scrolled .jcw-main-nav-link:hover,
[data-jcw-main-nav].jcw-nav-scrolled .jcw-main-nav-link:focus-visible {
  color: #1e3a8a;
}

.jcw-main-footer {
  background-color: var(--jcw-main-footer);
  border-color: #24345f;
}

.jcw-main-footer-strip {
  background-color: var(--jcw-main-footer-strip);
  color: #cbd5e1;
}

@media (max-width: 768px) {
  [data-jcw-mobile-menu] .jcw-mobile-nav-link,
  [data-jcw-mobile-menu] .jcw-mobile-nav-link:visited {
    color: #1e3a8a;
  }

  [data-jcw-mobile-menu] .jcw-mobile-nav-link:hover,
  [data-jcw-mobile-menu] .jcw-mobile-nav-link:focus-visible {
    color: #14214a;
  }
}
/* Homepage visual system */
.jcw-home-hero,
.jcw-main-footer,
.jcw-main-footer-strip {
  background-color: var(--jcw-blue-primary);
}

.jcw-home-light-section,
.jcw-home-cta-section {
  background-color: var(--jcw-home-neutral-light);
  color: #0f172a;
}

.jcw-home-blue-section {
  background-color: var(--jcw-home-neutral-alt);
  color: #0f172a;
}

.jcw-home-content-section,
.jcw-home-cta-section {
  border-top: 1px solid var(--jcw-home-border);
}

.jcw-home-cinematic-section {
  min-height: 86vh;
  padding-block: clamp(4.5rem, 7vw, 6.5rem);
}

.jcw-home-container {
  width: min(100% - 2rem, 80rem);
}

.jcw-home-section-heading {
  margin-bottom: clamp(2.5rem, 4vw, 3.5rem);
}

.jcw-home-section-heading > p:first-child {
  margin-bottom: 1rem;
  color: #1e3a8a;
  font-size: 0.75rem;
  line-height: 1.25rem;
  letter-spacing: 0.2em;
  font-weight: 700;
  text-transform: uppercase;
}

.jcw-home-section-heading h2 {
  color: #0f172a;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1.12;
  letter-spacing: -0.025em;
}

.jcw-home-section-heading > p:last-child {
  max-width: 44rem;
  margin-top: 1.25rem;
  color: #334155;
  font-size: clamp(1.0625rem, 1.6vw, 1.25rem);
  line-height: 1.65;
}

.jcw-home-card-grid {
  align-items: stretch;
}

.jcw-home-card {
  min-height: 100%;
  border: 1px solid var(--jcw-home-border);
  border-radius: 0.875rem;
  padding: clamp(1.75rem, 3vw, 2.5rem);
  background-color: #ffffff;
  box-shadow: none;
  color: #0f172a;
}

.jcw-home-card h3 {
  color: #0f172a;
  font-size: clamp(1.35rem, 2vw, 1.5rem);
  line-height: 1.25;
  letter-spacing: -0.015em;
}

.jcw-home-card p,
.jcw-home-blue-section .text-slate-300,
.jcw-home-blue-section .text-blue-100 {
  max-width: 34rem;
  margin-top: 1rem;
  color: #334155;
  font-size: 1.0625rem;
  line-height: 1.7;
}

.jcw-home-blue-section .jcw-home-section-heading > p:first-child {
  color: #1e3a8a;
}

.jcw-home-blue-section .jcw-home-card {
  background-color: #ffffff;
}

.jcw-home-secondary-cta {
  background-color: var(--jcw-blue-primary);
  border-color: var(--jcw-blue-primary);
  color: #ffffff;
}

.jcw-home-secondary-cta:hover,
.jcw-home-secondary-cta:focus-visible {
  background-color: var(--jcw-blue-primary);
  border-color: var(--jcw-blue-primary);
  color: #ffffff;
  opacity: 0.88;
}

.jcw-main-footer {
  border-top: 1px solid var(--jcw-home-border);
  border-color: var(--jcw-home-border);
}

.jcw-main-footer-strip {
  color: #dbeafe;
}

@media (max-width: 767px) {
  .jcw-home-cinematic-section {
    min-height: 0;
    padding-block: 4.5rem;
  }
}
.jcw-home-cta-actions > a {
  min-width: 11rem;
}

@media (max-width: 639px) {
  .jcw-home-cta-actions > a {
    width: 100%;
  }
}
